INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT105-S4-Q2$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Blues lyrics are usually about frustration, anger, oppression and restlessness.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Musicians find joy in performing the blues, and players and fans say its overall effect affirms life, love and hope?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$We need ways that singing about trouble can leave people feeling better. Shared experience, humor, perspective and release would all do it. Each working answer should connect the sad material to the positive effect.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Four choices give a way sad songs can produce joy or hope. The answer will not touch joy or hope at all.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT105-S4-Q2$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Sharing the music builds a supportive community. Belonging is a source of joy, even when the songs are about pain.$batch03$), ($batch03$B$batch03$, $batch03$This compares *success* between two kinds of musicians. It says nothing about why performing sad songs brings joy or hope to anyone, so it does not touch the conflict.$batch03$), ($batch03$C$batch03$, $batch03$Irony and wit give perspective on troubles. Laughing at hardship is one way sad material turns into affirmation.$batch03$), ($batch03$D$batch03$, $batch03$Hearing that others share your plight helps you cope. That turns songs about trouble into comfort.$batch03$), ($batch03$E$batch03$, $batch03$Turning sorrow into art can be cathartic for both performer and audience. Release is a direct route from sad lyrics to a good feeling.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT105-S4-Q2$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
